// Based on https://www.npmjs.com/package/foreground-child
const {spawn}=require('child_process');
function watch(child){const watchdogCode=`process.on('SIGHUP',()=>process.kill(${child.pid},'SIGHUP'));`;return spawn(process.execPath,['-e',watchdogCode,String(child.pid)],{stdio:'ignore'});}
module.exports=watch;
